// Answer the bands as records in constructor shape, so the table rebuilds from them with its bounds.
//
// `b := t.bounds(); fin.tiered_charges(t.bands(), b.min, b.max) == t`.
//
//kavun:member bands pure () -> array
func tieredChargesBands(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	t := TieredChargesOf(v)
	bs := t.Bands()
	out := make([]core.Value, len(bs))
	for i, b := range bs {
		out[i] = chargeBandValue(b)
	}
	return core.NewArrayValue(out, false), nil
}

