	t := TieredChargesOf(v)
	// {min, max}; a max of 0 means no cap
	lo, hi := t.Bounds()
	return core.NewRecordValue(map[string]core.Value{"min": core.NewDecimalValue(lo), "max": core.NewDecimalValue(hi)}, false), nil
